package com.seanglay.js_report;

import net.jsreport.java.JsReportException;
import net.jsreport.java.dto.*;
import net.jsreport.java.service.JsReportService;
import org.springframework.core.io.ClassPathResource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.*;

@RestController
public class TestController {

    private final JsReportService jsReportService;

    public TestController(JsReportService jsReportService) {
        this.jsReportService = jsReportService;
    }

    @GetMapping("/receipt")
    public ResponseEntity<byte[]> hello() throws IOException, JsReportException {
        ClassPathResource tpl = new ClassPathResource("templates/receipt.html");
        String html = new String(tpl.getInputStream().readAllBytes(), StandardCharsets.UTF_8);

        Chrome chrome = new Chrome();
        chrome.setFormat("A4");
        chrome.setDisplayHeaderFooter(Boolean.valueOf(true));
        chrome.setFooterTemplate("<div\n" +
                "      style=\"\n" +
                "        width: 100%;\n" +
                "        margin-left: -10mm;\n" +
                "        margin-right: -10mm;\n" +
                "        padding: 0 20mm;\n" +
                "        box-sizing: border-box;\n" +
                "        font-family: &quot;Khmer OS Content&quot;, Arial, sans-serif;\n" +
                "        font-size: 9px;\n" +
                "        color: #111;\n" +
                "      \"\n" +
                "    >\n" +
                "      <div style=\"line-height: 1.25; width: 100%\">\n" +
                "        <p style=\"margin: 0 0 2px 0\">\n" +
                "          <strong>សំគាល់១ \u00AD :</strong>\n" +
                "          លទ្ធផលនៃវិភាគនេះ មិនអាចប្រើប្រាស់សំរាប់ការផ្សព្វផ្សាយបានទេ\n" +
                "          និងមានតំលៃចំពោះតែគំរូដែលបានបញ្ជូនមកប៉ុណ្ណោះ។\n" +
                "        </p>\n" +
                "        <p style=\"margin: 0 0 2px 0\">\n" +
                "          លទ្ធផលវិភាគដោយ វិធីសាស្ត្រ MPN ដែលមានតម្លៃ < 3x100\n" +
                "          អនុលោមតាមស្ដង់ដារកំណត់ (3828)។ ទំព័រ 1/1\n" +
                "        </p>\n" +
                "        <div style=\"clear: both\"></div>\n" +
                "        <p style=\"margin: 0 0 2px 0\">\n" +
                "          <strong>Note 1:</strong> The result of analysis is not to be used for\n" +
                "          advertising purposes and results relate only to the items tested. >\n" +
                "        </p>\n" +
                "        <div style=\"clear: both\"></div>\n" +
                "        <p style=\"margin: 0 0 2px 0\">\n" +
                "          <strong>Note 2:</strong> The result of analysis &lt;3x100 by using MPN\n" +
                "          method conforms to standard. STINL does not engage in sampling.\n" +
                "        </p>\n" +
                "        <p style=\"margin: 0 0 2px 0\">\n" +
                "          <strong>Note 3:</strong> The report shall not be reproduced except in\n" +
                "          full, without writing approval of STINL.\n" +
                "        </p>\n" +
                "        <div style=\"margin: 0\">\n" +
                "          NATA is a signatory to the ILAC Mutual Recognition Arrangement for the\n" +
                "          mutual recognition of equivalence of testing reports.\n" +
                "        </div>\n" +
                "      </div>\n" +
                "    </div>");

        chrome.setHeaderTemplate("<div style='font-size:0; height:0;'></div>");

        Template template = new Template();
        template.setContent(html);
        template.setEngine(Engine.HANDLEBARS);
        template.setChrome(chrome);
        template.setRecipe(Recipe.CHROME_PDF);

        Map<String, Object> data = new HashMap<>();
        data.put("sampleNo", "COA-2026-000123");
        data.put("sampleKh", "ទឹកស៊ីអ៊ីវ");
        data.put("submittedDate", "2026-01-15");
        data.put("approvedDate", "2026-01-20");
        data.put("sampleProviderNameKh", "លោក សុខ វិសាល");

        Map<String, Object> applicant = new HashMap<>();
        applicant.put("nameKh", "លោក សុខ វិសាល");
        data.put("applicant", applicant);

        List<Map<String, Object>> items = new ArrayList<>();
        items.add(item(1, "Total Plate Count", "ISO 4833-1:2013", "&lt; 1.0 × 10⁴ CFU/g", "&lt; 10 CFU/g"));
        items.add(item(2, "E. coli", "ISO 16649-2:2001", "Absent / g", "Absent"));
        items.add(item(2, "E. coli", "ISO 16649-2:2001", "Absent / g", "Absent"));
        items.add(item(2, "E. coli", "ISO 16649-2:2001", "Absent / g", "Absent"));
        items.add(item(2, "E. coli", "ISO 16649-2:2001", "Absent / g", "Absent"));

        data.put("items", items);

        data.put("signatureStamp","data:image/png;base64,");


        data.put("qrcodeData","data:image/png;base64,");
        RenderRequest renderRequest = new RenderRequest();




        renderRequest.setTemplate(template);
        renderRequest.setData(data);

        Report report = jsReportService.render(renderRequest);
        byte[] pdf = report.getContent().readAllBytes();

        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_PDF)
                .header(HttpHeaders.CONTENT_DISPOSITION, "inline; filename=receipt.pdf")
                .body(pdf);
    }

    private static Map<String, Object> item(
            int no,
            String parameterName,
            String refMethods,
            String acceptableRangeDisplay,
            String resultDisplay
    ) {
        Map<String, Object> m = new HashMap<>();
        m.put("no", no);
        m.put("parameterName", parameterName);
        m.put("refMethods", refMethods);
        m.put("acceptableRangeDisplay", acceptableRangeDisplay);
        m.put("resultDisplay", resultDisplay);
        return m;
    }
}
